using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Object=UnityEngine.Object;
public static partial class Extension05Tools{
static void FinishExtension(){var s=Load("10005a");var all=All(s);art=all.First(t=>t.name=="10005a_Extension_Of_10001a");ground=all.Select(t=>t.GetComponent<Terrain>()).First(t=>t&&t.gameObject.activeInHierarchy);if(art.Find("07_Final_Forest_Continuity"))throw new Exception("Already finished");var group=Group("07_Final_Forest_Continuity");var cliff=Lib("SM_Cliff_Large_01");int c=0;foreach(var t in all.Where(t=>t.name.StartsWith("01a_Cliff_")&&t.gameObject.activeInHierarchy)){var b=B(t.gameObject);var g=Put(cliff,group,new Vector3(b.center.x,b.min.y,b.center.z),b.size.x,R(-10,10),"Grass_Capped_Cliff_"+c++,true);var nb=B(g);g.transform.localScale=Vector3.Scale(g.transform.localScale,new Vector3(1,b.size.y/nb.size.y,b.size.z/nb.size.z));nb=B(g);g.transform.position+=new Vector3(b.center.x-nb.center.x,b.min.y-nb.min.y,b.center.z-nb.center.z);t.gameObject.SetActive(false);}
var reference=Load("10001a");var refs=All(reference);var grass=refs.First(t=>t.name=="SM_Grass_01"&&t.gameObject.activeInHierarchy).gameObject;int patches=0;for(int i=0;i<6000;i++){var p=G(R(3,97),R(3,97),-.035f);if(p.y>8||p.y<3.15f||PathDistance(new Vector2(p.x,p.z))<2.8f||OnRiver(p,all))continue;float u=(p.x-ground.transform.position.x)/ground.terrainData.size.x,v=(p.z-ground.transform.position.z)/ground.terrainData.size.z;if(ground.terrainData.GetSteepness(u,v)>25)continue;if(Vector2.Distance(new Vector2(p.x,p.z),new Vector2(80,79))<9)continue;Put(grass,group,p,R(1.15f,1.85f),R(0,360),"Lush_01a_Grass_"+patches++);}
var tree=refs.FirstOrDefault(t=>t.name=="SM_Tree_01"&&t.gameObject.activeInHierarchy);if(tree){foreach(var v in new[]{new Vector2(18,25),new Vector2(29,33),new Vector2(20,50),new Vector2(38,54),new Vector2(71,40),new Vector2(87,48),new Vector2(74,62),new Vector2(90,71)})Put(tree.gameObject,group,G(v.x,v.y),R(3.3f,4.4f),R(0,360),"01a_Forest_Tree",true);}
var bridge=all.First(t=>t.name=="Carved_Footbridge");var bbridge=B(bridge.gameObject);var verts=new Vector3[26*4];var uv=new Vector2[verts.Length];var tris=new System.Collections.Generic.List<int>();for(int i=0;i<26;i++){float t=i/25f;float x=bbridge.min.x+.2f+t*(bbridge.size.x-.4f);float y=bridge.position.y-.07f+Mathf.Sin(t*Mathf.PI)*.3f;verts[i*4]=new Vector3(x,y,bbridge.center.z-1.28f);verts[i*4+1]=new Vector3(x,y,bbridge.center.z+1.28f);verts[i*4+2]=new Vector3(x,y-.5f,bbridge.center.z-1.15f);verts[i*4+3]=new Vector3(x,y-.5f,bbridge.center.z+1.15f);for(int j=0;j<4;j++)uv[i*4+j]=new Vector2(t*7,j%2);if(i<25){int a=i*4,b=a+4;tris.AddRange(new[]{a,a+1,b+1,a,b+1,b,a+2,a,b,a+2,b,b+2,a+1,a+3,b+3,a+1,b+3,b+1});}}
var mesh=new Mesh();mesh.vertices=verts;mesh.uv=uv;mesh.triangles=tris.ToArray();mesh.RecalculateNormals();AssetDatabase.CreateAsset(mesh,Root+"/Curved_Bridge_Stone_Core.asset");var core=new GameObject("Curved_Continuous_Masonry_Bridge_Core");core.transform.SetParent(group,false);core.AddComponent<MeshFilter>().sharedMesh=mesh;core.AddComponent<MeshRenderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>(Root+"/Carved_Grey_Moss_Stone.mat");
var spring=all.First(t=>t.name=="Irregular_Spring_Water").GetComponent<Renderer>();var stream=new GameObject("Spring_Fountain_Water_Flow");stream.transform.SetParent(group,false);var lr=stream.AddComponent<LineRenderer>();lr.positionCount=7;var start=G(83,86.7f,1.9f);var end=G(83,85.2f,.31f);for(int i=0;i<7;i++){float t=i/6f;var p=Vector3.Lerp(start,end,t);p.y+=Mathf.Sin(t*Mathf.PI)*.12f;lr.SetPosition(i,p);}lr.startWidth=.1f;lr.endWidth=.15f;lr.sharedMaterial=spring.sharedMaterial;lr.numCapVertices=4;lr.numCornerVertices=3;
AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(s);File.AppendAllText(W+"/outputs/Extension01a/Changes.txt","\nGrass topped cliff corrections: "+c+"; final meadow grass: "+patches+"; 01a trees, continuous curved stone bridge core and fountain water flow.\n");Capture();ValidateExtension();}
static void ValidateExtension(){var s=Load("10005a");var all=All(s);var td=all.Select(t=>t.GetComponent<Terrain>()).First(t=>t&&t.gameObject.activeInHierarchy);var lines=new System.Collections.Generic.List<string>();lines.Add("Scene="+s.path+" saved="+!s.isDirty);lines.Add("Terrain="+AssetDatabase.GetAssetPath(td.terrainData));lines.Add("TerrainCollider matches="+(td.GetComponent<TerrainCollider>().terrainData==td.terrainData));lines.Add("Grass patches="+all.Count(t=>t.gameObject.activeInHierarchy&&(t.name.StartsWith("01a_Grass_")||t.name.StartsWith("Rock_Foot_01a_Grass_")||t.name.StartsWith("Lush_01a_Grass_"))));lines.Add("Active old cave rocks="+all.Count(t=>t.gameObject.activeInHierarchy&&t.name.StartsWith("Cave_R")&&!t.name.Contains("LOD")));lines.Add("Old block spring active="+all.First(t=>t.name=="Ancient_Spring_Stonework").gameObject.activeInHierarchy);lines.Add("Missing mesh count="+all.Select(t=>t.GetComponent<MeshFilter>()).Count(m=>m&&m.gameObject.activeInHierarchy&&!m.sharedMesh));lines.Add("Missing material count="+all.Select(t=>t.GetComponent<Renderer>()).Where(r=>r&&r.gameObject.activeInHierarchy).Sum(r=>r.sharedMaterials.Count(m=>!m)));File.WriteAllLines(W+"/outputs/Extension01a/Validation.txt",lines);}
